INSERT INTO instruments (instrument_id, authority_id, lg_id, kind, force, title, notes) VALUES ($q$SBRC_PLANNING_SCHEME_2017$q$, $q$SBRC$q$, $q$SOUTH_BURNETT$q$, 'PLANNING_SCHEME', 'STATUTORY_INSTRUMENT', $q$South Burnett Regional Council Planning Scheme 2017$q$, $q$Every page footer reads "South Burnett Regional Council Planning Scheme | Effective from 28 October 2024 (Version 2.0)". Appendix 2 Table AP2.1 lists v2.0 as a Major Amendment adopted 16 October 2024 and effective 28 October 2024. The scheme commenced on 2 October 2017 (Government Gazette No. 31, 29 September 2017). The council site returned 403 on 2026-10-22, so we could not re-check online that v2.0 is still current; the PDF was downloaded earlier. QHC: the scheme does not mention the Queensland Housing Code (no match for "Housing Code"/"QHC" across all 320 pages), so there is no adoption statement.$q$);
