SELECT define_rule($q${"rule_id": "SBRC.sbrc_ldr_buildings_front", "instrument_version": "SBRC_PLANNING_SCHEME_2017@2024-10-28", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.1 AO2.5(a)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2024-10-28", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "SOUTH_BURNETT"}, {"level": "ZONE", "zone": "SBRC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "sbrc_ldr_buildings_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_front_setback_primary_street\", \"operator\": \">=\", \"value\": 6, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'buildings' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO - s1.6(4) says the building assessment provisions in the scheme are those in Table 1.6.1, which lists only the bushfire prone area designation; zone-code setbacks are not declared as QDC alternative provisions (s33 Building Act)\nResearcher notes: Table 5.5.1: a dwelling house is accepted development (no requirements) unless it is in the Bunya Mountains Precinct. There it is ADSR against Section 4 only, which has no setbacks. Code assessment arises only when the ADSR is not met, and s5.3.3(4)(b) then limits assessment to the subject matter of the failed Section 4 AOs. So this AO rarely, if ever, reaches a dwelling house or its domestic outbuildings. It applies directly to other code-assessable development, e.g. dual occupancy."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$SBRC.sbrc_ldr_buildings_front@2024-10-28$q$;
