INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SOUTH_BURNETT$q$, $q$SBRC_PLANNING_SCHEME_2017$q$, 'MEDIUM', $q$Do the "Small lot dwelling houses" setbacks (LDR AO12.1-12.3, MDR AO20.1-20.3: "For houses on lots less than 400m2") reach detached Class 10a domestic outbuildings or only the house? The Dwelling house definition includes domestic outbuildings.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SOUTH_BURNETT$q$, $q$SBRC_PLANNING_SCHEME_2017$q$, 'MEDIUM', $q$LDR AO2.5 and RR AO1.3 ("Buildings") reach a dwelling house only through code assessment, which s5.3.3(4)(b) appears to limit to the failed ADSR matters. Should they be treated as applying to Class 10 in practice?$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SOUTH_BURNETT$q$, $q$SBRC_PLANNING_SCHEME_2017$q$, 'MEDIUM', $q$Planning Regulation 2017 Sch 6 Pt 2 s2 limits when a planning scheme can make a dwelling house assessable. Check whether the Table 5.5.2 trigger (lot < 400 m2) and the secondary-dwelling triggers are effective.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SOUTH_BURNETT$q$, $q$SBRC_PLANNING_SCHEME_2017$q$, 'MEDIUM', $q$Rural AO1.1 depends on road hierarchy ("collector or higher order road"), which is not defined in SC1. A road hierarchy source is needed.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$SOUTH_BURNETT$q$, $q$SBRC_PLANNING_SCHEME_2017$q$, 'MEDIUM', $q$The council website returned 403, so we could not confirm online that Version 2.0 (effective 28 Oct 2024) is still the current version as at 2026-10-22.$q$);
